    "questionAr": "كرة كتلتها $m = 0.5\\text{ كجم}$ تتحرك بسرعة $12\\text{ م/ث}$ تلقت دفعاً في الاتجاه المضاد فارتدت بسرعة $8\\text{ م/ث}$. أوجد مقدار الدفع.",
