      "Change in momentum $\\Delta p = m(v_2 - v_1) = 0.5(-8 - 12) = 0.5(-20) = -10\\text{ kg}\\cdot\\text{m/s}$.",
      "Magnitude of impulse $|I| = 10\\text{ N}\\cdot\\text{s}$."
