    "hintEn": "Set up two equations: momentum conservation $m_1 u_1 = m_1 v_1 + m_2 v_2$, and restitution $v_2 - v_1 = e u_1$.",
    "hintAr": "اكتب معادلتي حفظ كمية الحركة: $m_1 u_1 = m_1 v_1 + m_2 v_2$، وقانون الارتداد: $v_2 - v_1 = e u_1$.",
